# ==========================================
# 2. 核心处理函数
# ==========================================

def get_task_info(benchmark_name, task_desc):
    """从 LIBERO Benchmark 中查找任务 ID"""
    bm = benchmark.get_benchmark(benchmark_name)()
    num_tasks = bm.get_num_tasks()
    for i in range(num_tasks):
        task = bm.get_task(i)
        if task_desc.lower() in task.language.lower():
            return bm, i, task
    raise ValueError(f"Task '{task_desc}' not found in {benchmark_name}")

def process_action(raw_action, stats):
    """
    逻辑：
    1. 接收模型输出 (8维)
    2. 填充到 (32维) 以匹配 stats
    3. 反归一化: action = (raw * std) + mean
    4. 截取前 (7维) 给 Robot 执行
    """
    # 1. 准备统计量 (确保长度为 32)
    mean = np.array(stats["actions"]["mean"])
    std = np.array(stats["actions"]["std"])
    
    if len(mean) < 32:
        mean = np.pad(mean, (0, 32 - len(mean)), 'constant')
    if len(std) < 32:
        std = np.pad(std, (0, 32 - len(std)), 'constant')

    # 2. 准备输入动作 (确保是 numpy array)
    action_in = np.array(raw_action) # 应该是 8 维
    
    # 3. 填充输入到 32 维
    action_full = np.zeros(32)
    current_dim = len(action_in)
    action_full[:current_dim] = action_in
    
    # 4. 反归一化
    unnormalized_full = (action_full * std) + mean
    
    # 5. 截取前 7 维 (x, y, z, ax, ay, az, gripper)
    # LIBERO 环境只需要这 7 个值
    env_action = unnormalized_full[:7]
    
    return env_action

# ==========================================
# 3. 可视化主程序
# ==========================================

def run_visualization(action_sequence):
    print(">>> 初始化 LIBERO 环境...")
    bm, task_id, task = get_task_info(BENCHMARK_NAME, TASK_DESCRIPTION)
    
    # 初始化环境参数
    env_args = {
        "bddl_file_name": os.path.join("/ytech_m2v8_hdd/workspace/kling_mm/daiyifan/LIBERO/libero/libero/bddl_files", task.problem_folder, task.bddl_file),
        "camera_heights": 256,
        "camera_widths": 256,
        "camera_names": ["agentview", "robot0_eye_in_hand"],
        "render_gpu_device_id":0
    }
    
    env = OffScreenRenderEnv(**env_args)
    env.seed(0)
    
    # 设置初始状态 (非常重要，否则任务无法复现)
    env.reset()
    init_states = bm.get_task_init_states(task_id)
    env.set_init_state(init_states[0])
    
    obs = env.reset()
    
    # 视频录制器
    video_path = "libero_execution.mp4"
    writer = imageio.get_writer(video_path, fps=30)
    
    print(f">>> 开始执行动作序列 (共 {len(action_sequence)} 步)...")
    
    success = False
    
    for i, raw_action in enumerate(action_sequence):
        # --- 核心：处理动作 ---
        env_action = process_action(raw_action, NORM_STATS)
        
        # --- 执行 ---
        obs, reward, done, info = env.step(env_action)
        
        # --- 渲染与记录 ---
        # 翻转图像，因为有时候 OpenGL 渲染出来是倒的
        frame = obs["agentview_image"]
        frame = frame[::-1] # 如果画面是倒的，取消注释这一行；如果是正常的，注释掉
        writer.append_data(frame)
        
        if (i + 1) % 10 == 0:
            print(f"    Step {i+1}/{len(action_sequence)}")
            
        # --- 检查是否成功 ---
        if env.check_success():
            success = True
            print(f"!!! 任务在第 {i+1} 步检测为成功 !!!")
            # 注意：即使成功也可以继续跑完动作，看看后续是否保持稳定
    
    writer.close()
    env.close()
    
    print("-" * 30)
    print(f"可视化完成。视频已保存至: {video_path}")
    print(f"最终评估结果: {'SUCCESS' if success else 'FAIL'}")
    print("-" * 30)

